{
  "name": "ClickMaster AI - High-CTR Thumbnail Studio",
  "description": "A professional AI-powered thumbnail generator that applies deep psychological principles and visual salience to maximize CTR using Gemini 3 Pro.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface VideoInfo {
  title: string;
  description: string;
  category: string;
}

export interface PsychologicalHook {
  type: 'Negativity' | 'Curiosity' | 'SocialProof' | 'Authority';
  label: string;
  copy: string;
  psychology: string;
}

export interface ThumbnailResult {
  imageUrl: string;
  hooks: PsychologicalHook[];
  analysis: string;
}

export enum GenerationStatus {
  IDLE = 'IDLE',
  ANALYZING = 'ANALYZING',
  GENERATING_IMAGE = 'GENERATING_IMAGE',
  SUCCESS = 'SUCCESS',
  ERROR = 'ERROR'
}

import { GoogleGenAI, Type } from "@google/genai";
import { VideoInfo, PsychologicalHook } from "../types";

export class GeminiService {
  private static instance: GeminiService;

  private constructor() {}

  static getInstance() {
    if (!this.instance) {
      this.instance = new GeminiService();
    }
    return this.instance;
  }

  async analyzeVideoInfo(info: VideoInfo): Promise<{ hooks: PsychologicalHook[], analysis: string }> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `You are a world-class YouTube growth strategist. Analyze this video info and generate 4 psychological hooks for a high-CTR thumbnail.

      Video Title: ${info.title}
      Video Description: ${info.description}
      Category: ${info.category}

      Requirements for hooks:
      1. Negativity Bias (Loss aversion)
      2. Information Gap (Curiosity)
      3. Social Proof (FOMO)
      4. Authority (Expertise)

      Return the output strictly in JSON format matching the schema provided.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            analysis: { type: Type.STRING, description: "Strategic analysis of why these hooks work." },
            hooks: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  type: { type: Type.STRING, enum: ['Negativity', 'Curiosity', 'SocialProof', 'Authority'] },
                  label: { type: Type.STRING },
                  copy: { type: Type.STRING, description: "Short catchy text for the thumbnail (Korean preferred)" },
                  psychology: { type: Type.STRING, description: "Brief explanation of the psychological trigger used." }
                },
                required: ['type', 'label', 'copy', 'psychology']
              }
            }
          },
          required: ['analysis', 'hooks']
        }
      }
    });

    return JSON.parse(response.text);
  }

  async generateThumbnail(prompt: string, referenceImage?: string): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const parts: any[] = [
      { text: `High-CTR YouTube thumbnail style, professional lighting, vibrant colors, high contrast, Rule of Thirds composition. Focus: ${prompt}. Cinematic quality, 4K resolution, vivid textures. The person in the image should have an exaggerated facial expression (e.g., extreme shock, anger, or mysterious smile) to trigger mirror neurons. Keep the background simple and out-of-focus (bokeh) to highlight the subject. Use bright visual cues like arrows or circles if appropriate.` }
    ];

    if (referenceImage) {
      parts.push({
        inlineData: {
          mimeType: "image/jpeg",
          data: referenceImage.split(',')[1]
        }
      });
      parts[0].text += " Incorporate the character/object from the provided reference image seamlessly into this new professional thumbnail composition.";
    }

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: { parts },
      config: {
        imageConfig: {
          aspectRatio: "16:9",
          imageSize: "1K"
        }
      }
    });

    let imageUrl = '';
    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) {
        imageUrl = `data:image/png;base64,${part.inlineData.data}`;
        break;
      }
    }

    if (!imageUrl) throw new Error("Image generation failed to return data.");
    return imageUrl;
  }
}

import React, { useState, useEffect, useCallback } from 'react';
import { VideoInfo, ThumbnailResult, GenerationStatus, PsychologicalHook } from './types';
import { GeminiService } from './services/geminiService';

// --- Sub-components (defined outside to avoid re-renders) ---

const LoadingOverlay: React.FC<{ status: GenerationStatus }> = ({ status }) => {
  const getMessage = () => {
    switch (status) {
      case GenerationStatus.ANALYZING: return "심리학적 전략 분석 중...";
      case GenerationStatus.GENERATING_IMAGE: return "고해상도 썸네일 렌더링 중 (약 10-20초 소요)...";
      default: return "준비 중...";
    }
  };

  return (
    <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-50 flex flex-col items-center justify-center p-6 text-center">
      <div className="w-16 h-16 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mb-6"></div>
      <h2 className="text-2xl font-bold text-white mb-2">{getMessage()}</h2>
      <p className="text-slate-400 max-w-md">Gemini 3 Pro가 최고의 클릭률을 보장하는 시각적 요소를 계산하고 있습니다.</p>
    </div>
  );
};

const ApiKeyPrompt: React.FC<{ onComplete: () => void }> = ({ onComplete }) => {
  const handleOpenKey = async () => {
    // @ts-ignore
    await window.aistudio.openSelectKey();
    onComplete();
  };

  return (
    <div className="bg-slate-800 p-8 rounded-2xl border border-slate-700 shadow-2xl max-w-lg mx-auto text-center">
      <div className="w-16 h-16 bg-indigo-500/20 rounded-full flex items-center justify-center mx-auto mb-6">
        <svg className="w-8 h-8 text-indigo-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 7a2 2 0 012 2m4 0a6 6 0 01-7.743 5.743L11 17H9v2H7v2H4a1 1 0 01-1-1v-2.586a1 1 0 01.293-.707l5.964-5.964A6 6 0 1121 9z" /></svg>
      </div>
      <h2 className="text-2xl font-bold mb-4">Gemini 3 Pro 활성화 필요</h2>
      <p className="text-slate-400 mb-6">
        고퀄리티 썸네일 제작을 위해 <b>Gemini 3 Pro Image</b> 모델을 사용합니다. 
        사용하시려면 유료 결제가 활성화된 API 키 선택이 필요합니다.
      </p>
      <div className="bg-amber-500/10 border border-amber-500/20 p-4 rounded-lg mb-8 text-sm text-amber-200">
        <p>💡 결제 정보가 없는 키는 이미지 생성이 거부될 수 있습니다.</p>
        <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" className="underline font-bold block mt-1">결제 문서 확인하기</a>
      </div>
      <button 
        onClick={handleOpenKey}
        className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-4 rounded-xl transition-all shadow-lg"
      >
        API 키 선택/관리하기
      </button>
    </div>
  );
};

const App: React.FC = () => {
  const [videoInfo, setVideoInfo] = useState<VideoInfo>({ title: '', description: '', category: 'Entertainment' });
  const [refImage, setRefImage] = useState<string | null>(null);
  const [status, setStatus] = useState<GenerationStatus>(GenerationStatus.IDLE);
  const [result, setResult] = useState<ThumbnailResult | null>(null);
  const [hasKey, setHasKey] = useState<boolean>(false);
  const [selectedHook, setSelectedHook] = useState<PsychologicalHook | null>(null);

  useEffect(() => {
    const checkKey = async () => {
      // @ts-ignore
      const ok = await window.aistudio.hasSelectedApiKey();
      setHasKey(ok);
    };
    checkKey();
  }, []);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setRefImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const generate = async () => {
    if (!videoInfo.title) return alert("영상 제목을 입력해주세요.");

    try {
      setStatus(GenerationStatus.ANALYZING);
      const service = GeminiService.getInstance();

      // Phase 1: Analyze & Generate Hooks
      const analysisData = await service.analyzeVideoInfo(videoInfo);

      // Phase 2: Generate Image based on the best curiosity hook
      setStatus(GenerationStatus.GENERATING_IMAGE);
      const mainHook = analysisData.hooks[1] || analysisData.hooks[0]; // Usually Curiosity hook is best for visual gen
      const imageUrl = await service.generateThumbnail(
        `A high-impact thumbnail for a video titled "${videoInfo.title}". The theme is: ${mainHook.copy}. Incorporate psychological triggers: ${mainHook.psychology}.`,
        refImage || undefined
      );

      setResult({
        imageUrl,
        hooks: analysisData.hooks,
        analysis: analysisData.analysis
      });
      setSelectedHook(mainHook);
      setStatus(GenerationStatus.SUCCESS);
    } catch (err: any) {
      console.error(err);
      if (err.message.includes("Requested entity was not found")) {
        setHasKey(false);
        alert("API 키가 올바르지 않거나 만료되었습니다. 다시 선택해주세요.");
      } else {
        alert("생성 중 오류가 발생했습니다: " + err.message);
      }
      setStatus(GenerationStatus.ERROR);
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 selection:bg-indigo-500/30">
      {/* Header */}
      <nav className="border-b border-slate-800 bg-slate-900/50 backdrop-blur-md sticky top-0 z-40">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center shadow-lg shadow-indigo-500/20">
              <svg className="w-5 h-5 text-white" fill="currentColor" viewBox="0 0 20 20"><path d="M2 6a2 2 0 012-2h6a2 2 0 012 2v8a2 2 0 01-2 2H4a2 2 0 01-2-2V6zM14.553 7.106A1 1 0 0014 8v4a1 1 0 00.553.894l2 1A1 1 0 0018 13V7a1 1 0 00-1.447-.894l-2 1z" /></svg>
            </div>
            <span className="font-bold text-xl tracking-tight">ClickMaster <span className="text-indigo-400">AI</span></span>
          </div>
          <div className="hidden md:flex gap-6 text-sm font-medium text-slate-400">
            <a href="#" className="hover:text-white">가이드</a>
            <a href="#" className="hover:text-white">심리학 분석</a>
            <a href="#" className="hover:text-white">갤러리</a>
          </div>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-4 py-8 md:py-12">
        {!hasKey ? (
          <div className="mt-12">
            <ApiKeyPrompt onComplete={() => setHasKey(true)} />
          </div>
        ) : (
          <div className="grid lg:grid-cols-12 gap-12">

            {/* Left: Input Form */}
            <div className="lg:col-span-5 space-y-8">
              <section className="bg-slate-900 rounded-3xl p-8 border border-slate-800 shadow-xl">
                <h2 className="text-xl font-bold mb-6 flex items-center gap-2">
                  <span className="w-1.5 h-6 bg-indigo-500 rounded-full"></span>
                  영상 정보 입력
                </h2>

                <div className="space-y-6">
                  <div>
                    <label className="block text-sm font-medium text-slate-400 mb-2">영상 제목 (핵심 키워드 포함)</label>
                    <input 
                      type="text" 
                      className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                      placeholder="예: 3개월 만에 1억 번 비결 공개"
                      value={videoInfo.title}
                      onChange={(e) => setVideoInfo({...videoInfo, title: e.target.value})}
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-slate-400 mb-2">영상 내용 요약 (스크립트/설명)</label>
                    <textarea 
                      rows={4}
                      className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 focus:ring-2 focus:ring-indigo-500 outline-none transition-all resize-none"
                      placeholder="영상의 주요 내용을 적어주세요. AI가 심리학적 트리거를 분석합니다."
                      value={videoInfo.description}
                      onChange={(e) => setVideoInfo({...videoInfo, description: e.target.value})}
                    />
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="block text-sm font-medium text-slate-400 mb-2">카테고리</label>
                      <select 
                        className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 outline-none"
                        value={videoInfo.category}
                        onChange={(e) => setVideoInfo({...videoInfo, category: e.target.value})}
                      >
                        <option>Entertainment</option>
                        <option>Business/Finance</option>
                        <option>Tech/Review</option>
                        <option>Vlog/Lifestyle</option>
                        <option>Education</option>
                      </select>
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-slate-400 mb-2">참고 이미지 (선택)</label>
                      <label className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 flex items-center justify-center cursor-pointer hover:bg-slate-700 transition-colors">
                        <svg className="w-5 h-5 text-slate-400 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                        <span className="text-sm">{refImage ? "교체하기" : "업로드"}</span>
                        <input type="file" className="hidden" accept="image/*" onChange={handleImageUpload} />
                      </label>
                    </div>
                  </div>

                  {refImage && (
                    <div className="relative group">
                      <img src={refImage} alt="Ref" className="w-full h-32 object-cover rounded-xl border border-slate-700" />
                      <button 
                        onClick={() => setRefImage(null)}
                        className="absolute top-2 right-2 bg-red-500 p-1 rounded-full opacity-0 group-hover:opacity-100 transition-opacity"
                      >
                        <svg className="w-4 h-4 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
                      </button>
                    </div>
                  )}

                  <button 
                    onClick={generate}
                    disabled={status !== GenerationStatus.IDLE && status !== GenerationStatus.SUCCESS && status !== GenerationStatus.ERROR}
                    className="w-full bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-800 disabled:text-slate-600 text-white font-bold py-4 rounded-2xl transition-all shadow-lg shadow-indigo-500/20 text-lg flex items-center justify-center gap-2"
                  >
                    {status === GenerationStatus.IDLE || status === GenerationStatus.SUCCESS || status === GenerationStatus.ERROR ? (
                      <>
                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                        최적화 썸네일 생성하기
                      </>
                    ) : (
                      "AI 작업 중..."
                    )}
                  </button>
                </div>
              </section>

              {/* Psychological Tips */}
              <div className="bg-indigo-900/10 border border-indigo-500/20 rounded-3xl p-6">
                <h3 className="text-indigo-400 font-bold mb-3 flex items-center gap-2">
                  <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path d="M11 3a1 1 0 10-2 0v1a1 1 0 102 0V3zM15.657 5.757a1 1 0 00-1.414-1.414l-.707.707a1 1 0 001.414 1.414l.707-.707zM18 10a1 1 0 01-1 1h-1a1 1 0 110-2h1a1 1 0 011 1zM5.05 6.464A1 1 0 106.464 5.05l-.707-.707a1 1 0 00-1.414 1.414l.707.707zM5 10a1 1 0 01-1 1H3a1 1 0 110-2h1a1 1 0 011 1zM8 16v-1a1 1 0 112 0v1a1 1 0 11-2 0zM13.536 14.95a1 1 0 011.414 0l.707.707a1 1 0 11-1.414 1.414l-.707-.707a1 1 0 010-1.414zM6.464 14.95l-.707.707a1 1 0 11-1.414-1.414l.707-.707a1 1 0 111.414 1.414z" /></svg>
                  심리학적 치트시트
                </h3>
                <ul className="text-sm space-y-2 text-slate-400">
                  <li>• <b>부정적 편향:</b> "절대 하지 마세요"는 본능적 생존욕을 자극합니다.</li>
                  <li>• <b>정보 공백:</b> 결과를 숨기는 화살표는 강력한 호기심을 유발합니다.</li>
                  <li>• <b>시각적 현저성:</b> 형광색 테두리와 보색 대비는 시선을 강탈합니다.</li>
                </ul>
              </div>
            </div>

            {/* Right: Result Display */}
            <div className="lg:col-span-7">
              {result ? (
                <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
                  <section className="bg-slate-900 rounded-3xl p-8 border border-slate-800 shadow-xl overflow-hidden">
                    <div className="flex justify-between items-center mb-6">
                      <h2 className="text-xl font-bold flex items-center gap-2">
                        <span className="w-1.5 h-6 bg-emerald-500 rounded-full"></span>
                        생성된 마스터 썸네일
                      </h2>
                      <div className="flex gap-2">
                        <button className="p-2 bg-slate-800 rounded-lg hover:bg-slate-700 transition-colors">
                          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                        </button>
                        <button className="p-2 bg-slate-800 rounded-lg hover:bg-slate-700 transition-colors">
                          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z" /></svg>
                        </button>
                      </div>
                    </div>

                    <div className="relative group rounded-2xl overflow-hidden aspect-video bg-slate-800 mb-8 border border-slate-700 shadow-2xl">
                      <img src={result.imageUrl} alt="Thumbnail" className="w-full h-full object-cover" />

                      {/* Mobile Preview Overlay Simulation */}
                      <div className="absolute bottom-2 right-2 bg-black/80 px-1.5 py-0.5 rounded text-xs font-bold text-white z-10">
                        10:24
                      </div>

                      {/* Psychology Overlay (Visual Salience markers) */}
                      <div className="absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center bg-black/40 pointer-events-none">
                        <div className="border-2 border-dashed border-white/50 w-full h-full absolute inset-0 grid grid-cols-3 grid-rows-3">
                          <div className="border border-white/20"></div><div className="border border-white/20"></div><div className="border border-white/20"></div>
                          <div className="border border-white/20"></div><div className="border border-white/20"></div><div className="border border-white/20"></div>
                          <div className="border border-white/20"></div><div className="border border-white/20"></div><div className="border border-white/20"></div>
                        </div>
                        <span className="bg-white/20 backdrop-blur px-3 py-1 rounded-full text-xs font-medium">3분할 구도 (Rule of Thirds) 적용</span>
                      </div>
                    </div>

                    <div className="grid md:grid-cols-2 gap-4">
                      {result.hooks.map((hook, idx) => (
                        <button 
                          key={idx}
                          onClick={() => setSelectedHook(hook)}
                          className={`text-left p-4 rounded-2xl border transition-all ${selectedHook?.type === hook.type ? 'bg-indigo-600 border-indigo-400 shadow-lg shadow-indigo-600/20' : 'bg-slate-800 border-slate-700 hover:border-slate-500'}`}
                        >
                          <div className="flex justify-between items-start mb-2">
                            <span className={`text-[10px] font-bold uppercase tracking-wider px-2 py-0.5 rounded ${selectedHook?.type === hook.type ? 'bg-indigo-400 text-indigo-950' : 'bg-slate-700 text-slate-300'}`}>
                              {hook.label}
                            </span>
                          </div>
                          <p className="font-bold text-lg mb-1 leading-tight">{hook.copy}</p>
                          <p className={`text-xs ${selectedHook?.type === hook.type ? 'text-indigo-200' : 'text-slate-500'}`}>
                            {hook.psychology}
                          </p>
                        </button>
                      ))}
                    </div>
                  </section>

                  {/* Strategic Analysis */}
                  <section className="bg-slate-900 rounded-3xl p-8 border border-slate-800 shadow-xl">
                    <h3 className="text-xl font-bold mb-4 flex items-center gap-2">
                      <svg className="w-6 h-6 text-amber-400" fill="currentColor" viewBox="0 0 20 20"><path d="M10 12a2 2 0 100-4 2 2 0 000 4z" /><path fillRule="evenodd" d="M.458 10C1.732 5.943 5.522 3 10 3s8.268 2.943 9.542 7c-1.274 4.057-5.064 7-9.542 7S1.732 14.057.458 10zM14 10a4 4 0 11-8 0 4 4 0 018 0z" clipRule="evenodd" /></svg>
                      AI 마케팅 전략 리포트
                    </h3>
                    <div className="prose prose-invert max-w-none text-slate-400">
                      <p className="whitespace-pre-wrap leading-relaxed">{result.analysis}</p>
                    </div>

                    <div className="mt-8 pt-6 border-t border-slate-800 grid grid-cols-3 gap-4 text-center">
                      <div>
                        <div className="text-2xl font-bold text-emerald-400">89%</div>
                        <div className="text-xs text-slate-500 uppercase tracking-widest mt-1">예상 클릭률</div>
                      </div>
